H.background();
const v = H.plot2d({ xMin: 0, xMax: 7, yMin: -1, yMax: 22 });
v.grid(); v.axes();
const v0 = P.v0, h0 = P.h0, g = P.g;
const f = x => -0.5 * g * x * x + v0 * x + h0;
v.fn(f, { color: H.colors.accent, width: 3 });
const tpk = g > 1e-6 ? v0 / g : 0;
const hpk = f(tpk);
if (tpk >= 0 && tpk <= 7) {
  v.line(tpk, -1, tpk, hpk, { color: H.colors.violet, width: 1.2, dash: [4, 4] });
  v.dot(tpk, hpk, { r: 6, fill: H.colors.warn });
}
const disc = v0 * v0 + 2 * g * h0;
let land = 0;
if (g > 1e-6 && disc >= 0) {
  land = (v0 + Math.sqrt(disc)) / g;
  if (land >= 0 && land <= 7) v.dot(land, 0, { r: 6, fill: H.colors.good });
}
const span = Math.max(0.5, Math.min(7, land || tpk * 2 || 5));
const xs = (t * 0.9) % span;
v.dot(xs, Math.max(0, f(xs)), { r: 7, fill: H.colors.accent2 });
H.text("Quadratic model:  h(t) = −½g·t² + v₀·t + h₀", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("v₀=" + v0.toFixed(1) + "  h₀=" + h0.toFixed(1) + "  g=" + g.toFixed(1) + "   peak " + hpk.toFixed(1) + " at t=" + tpk.toFixed(2) + "s", 24, 52, { color: H.colors.sub, size: 12 });
